insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_81_v1'
from (values
('127.671.d.1.A',3,'A help-desk technician answers user calls, resets passwords and logs problems. These are the duties of a particular:','["job opportunity", "fire drill plan", "lunch menu", "school bus route"]'::jsonb,0,'Job duties describe what a worker does.','original'),
('127.671.d.1.A',4,'Reading a posting that lists tasks, required skills and pay is a way to learn about job:','["colors and fonts", "duties and requirements", "parking and meals", "weather and sports"]'::jsonb,1,'Postings describe the work.','original'),
('127.671.d.1.B',3,'Looking up the training, certifications and abilities an IT career requires is called:','["window shopping", "file sorting", "career research", "network gaming"]'::jsonb,2,'Research helps you plan your path.','original'),
('127.671.d.1.B',4,'A student interested in cybersecurity should research which of the following?','["office furniture brands", "favorite snacks of analysts", "company mascots", "required education and certifications"]'::jsonb,3,'Plan the education needed.','original'),
('127.671.d.1.C',3,'A document that summarizes your education, skills and experience for employers is a:','["resume", "firewall", "router", "spreadsheet"]'::jsonb,0,'Resumes market your qualifications.','original'),
('127.671.d.1.C',4,'A collection of your best projects and certificates that shows your work to employers is a:','["hard drive", "portfolio", "bookmark", "modem"]'::jsonb,1,'Portfolios show proof of ability.','original'),
('127.671.d.2.A',3,'Artificial intelligence, cloud computing and virtual reality are examples of:','["paper forms", "office supplies", "emerging technologies", "obsolete tools"]'::jsonb,2,'New technologies keep changing the field.','original'),
('127.671.d.2.A',4,'A technology that delivers storage and computing over the internet instead of on a local machine is:','["a floppy drive", "a card reader", "a dot-matrix printer", "cloud computing"]'::jsonb,3,'Cloud services run on remote servers.','original'),
('127.671.d.2.B',3,'Attaching a report to an email lets you send a:','["file along with your message", "keyboard through the air", "monitor with the email", "printer into the message"]'::jsonb,0,'Attachments carry files.','original'),
('127.671.d.2.B',4,'Before emailing a large video file, a user may need to:','["turn off the monitor", "compress the file or use a sharing link", "remove the keyboard", "delete the recipient"]'::jsonb,1,'Large attachments often exceed limits.','original'),
('127.671.d.2.C',3,'Using the word AND between two search terms narrows a search because it requires:','["only the first term", "neither term", "both terms to appear", "any unrelated term"]'::jsonb,2,'Boolean AND limits results.','original'),
